  col_appname: { bg:'Приложение (напр. видеокамери)', ru:'Приложение (напр. видеокамеры)', uk:'Застосунок (напр. відеокамери)', en:'App (e.g. cameras)', de:'App (z. B. Kameras)', fr:'App (ex. caméras)', es:'App (p. ej. cámaras)', 'es-MX':'App (p. ej. cámaras)', it:'App (es. videocamere)', pt:'App (ex. câmeras)', ar:'التطبيق (مثل الكاميرات)', hi:'ऐप (जैसे कैमरे)', ja:'アプリ（例：カメラ）', ky:'Тиркеме (мис. камералар)', 'zh-Hant':'應用程式（如攝影機）' },
