  legacy_create: { bg:'Създай и запази пакета', ru:'Создать и сохранить пакет', uk:'Створити та зберегти пакет', en:'Create and save the package', de:'Paket erstellen und speichern', fr:'Créer et enregistrer le paquet', es:'Crear y guardar el paquete', 'es-MX':'Crear y guardar el paquete', it:'Crea e salva il pacchetto', pt:'Criar e guardar o pacote', ar:'إنشاء الحزمة وحفظها', hi:'पैकेज बनाएँ और सहेजें', ja:'パッケージを作成して保存', ky:'Пакетти түзүп сактоо', 'zh-Hant':'建立並儲存套件' },
